#!/bin/sh
# ──────────────────────────────────────────────────────────────────────────────
# Seed dynamic public content collections in Directus.
#
# Creates/updates records idempotently for:
#   - memorial_entries
#   - gallery_categories
#   - gallery_items
#   - faculties
#   - faculty_departments
#   - vacancies
#
# Also uploads mock image files (if missing) and links them from memorial/gallery.
# ──────────────────────────────────────────────────────────────────────────────
set -eu

API="${PUBLIC_URL:-http://localhost:8055}"
EMAIL="${ADMIN_EMAIL:?ADMIN_EMAIL must be set}"
PASSWORD="${ADMIN_PASSWORD:?ADMIN_PASSWORD must be set}"

log() { printf '[seed-content] %s\n' "$*"; }

extract_first_id() {
  printf '%s' "$1" | sed -n 's/.*"id":"\([^"]*\)".*/\1/p'
}

api_json() {
  # $1 = method, $2 = path, $3 (optional) = json body
  if [ "$#" -ge 3 ]; then
    curl -sS -X "$1" "$API$2" -H "$AUTH" -H 'Content-Type: application/json' -d "$3"
  else
    curl -sS -X "$1" "$API$2" -H "$AUTH"
  fi
}

api_file_upload() {
  # $1 = file path, $2 = filename_download
  curl -sS -X POST "$API/files" \
    -H "$AUTH" \
    -F "file=@$1;filename=$2"
}

upsert_single() {
  # $1 collection, $2 query_url, $3 create_json, $4 update_json
  COLLECTION=$1
  QUERY_URL=$2
  CREATE_BODY=$3
  UPDATE_BODY=$4

  FOUND=$(api_json GET "$QUERY_URL")
  FOUND_ID=$(extract_first_id "$FOUND")

  if [ -n "$FOUND_ID" ]; then
    api_json PATCH "/items/$COLLECTION/$FOUND_ID" "$UPDATE_BODY" >/dev/null
    printf '%s' "$FOUND_ID"
    return
  fi

  CREATED=$(api_json POST "/items/$COLLECTION" "$CREATE_BODY")
  CREATED_ID=$(extract_first_id "$CREATED")
  if [ -z "$CREATED_ID" ]; then
    log "Failed to create item in $COLLECTION. Response: $CREATED"
    exit 1
  fi
  printf '%s' "$CREATED_ID"
}

ensure_file() {
  # $1 filename_download, $2 local_path
  FILE_NAME=$1
  LOCAL_PATH=$2
  FOUND=$(api_json GET "/files?filter%5Bfilename_download%5D%5B_eq%5D=$FILE_NAME&fields=id,filename_download&limit=1")
  FILE_ID=$(extract_first_id "$FOUND")
  if [ -n "$FILE_ID" ]; then
    printf '%s' "$FILE_ID"
    return
  fi

  UPLOADED=$(api_file_upload "$LOCAL_PATH" "$FILE_NAME")
  FILE_ID=$(extract_first_id "$UPLOADED")
  if [ -z "$FILE_ID" ]; then
    log "Failed to upload file $FILE_NAME. Response: $UPLOADED"
    exit 1
  fi
  printf '%s' "$FILE_ID"
}

log "Logging in as $EMAIL..."
LOGIN_RESPONSE=$(
  curl -sS -X POST "$API/auth/login" \
    -H 'Content-Type: application/json' \
    -d "{\"email\":\"$EMAIL\",\"password\":\"$PASSWORD\"}"
)
TOKEN=$(printf '%s' "$LOGIN_RESPONSE" | sed -n 's/.*"access_token":"\([^"]*\)".*/\1/p')
if [ -z "$TOKEN" ]; then
  log "Login failed: $LOGIN_RESPONSE"
  exit 1
fi
AUTH="Authorization: Bearer $TOKEN"

