MOCK_PNG_BASE64='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8Xw8AAoMBgX6lz2EAAAAASUVORK5CYII='

make_mock_image() {
  # $1 output path
  printf '%s' "$MOCK_PNG_BASE64" | base64 -d >"$1"
}

make_mock_document() {
